def show_help 
  help = "Never worked a jukebox, eh? Pretty standard. 
Available commands are:\n" 
  help += "'help' - shows this menu\n" 
  help += "'list' - lists the whole song library\n" 

  help += "or you can enter an artist's name to show that 
artist's songs\n" 
  puts help 
End 
